window.__finlexDocLoaded(184,{"id":184,"articles":[{"id":4598,"no":"第一条","heading":"","text":"为了规范注册会计师在执行首次审计业务时对期初余额的责任，制定本准则。","seq":0},{"id":4599,"no":"第二条","heading":"","text":"当财务报表包括比较财务信息时，《中国注册会计师审计准则第1511号——比较信息：对应数据和比较财务报表》的规定同样适用。《中国注册会计师审计准则第1201号——计划审计工作》对首次审计业务开始前的活动提出补充要求。 ## 第二章 定义","seq":1},{"id":4600,"no":"第三条","heading":"","text":"首次审计业务，是指在上期财务报表未经审计，或上期财务报表由前任注册会计师审计的情况下承接的审计业务。","seq":2},{"id":4601,"no":"第四条","heading":"","text":"期初余额，是指期初存在的账户余额。期初余额以上期期末余额为基础，反映了以前期间的交易和事项以及上期采用的会计政策的结果。期初余额也包括期初存在的需要披露的事项，如或有事项和承诺事项。","seq":3},{"id":4602,"no":"第五条","heading":"","text":"前任注册会计师，是指已对被审计单位上期财务报表进行审计，但被现任注册会计师接替的其他会计师事务所的注册会计师。 ## 第三章 目标","seq":4},{"id":4603,"no":"第六条","heading":"","text":"在执行首次审计业务时，注册会计师针对期初余额的目标是，获取充分、适当的审计证据以确定： **（一）期初余额是否含有对本期财务报表产生重大影响的错报；** （二）期初余额反映的恰当的会计政策是否在本期财务报表中得到一贯运用，或会计政策的变更是否已按照适用的财务报告编制基础作出恰当的会计处理和适当的列报。 ## 第四章 要求 ### 第一节 审计程序","seq":5},{"id":4604,"no":"第七条","heading":"","text":"注册会计师应当阅读最近期间的财务报表和前任注册会计师出具的审计报告（如有），获取与期初余额相关的信息，包括披露。","seq":6},{"id":4605,"no":"第八条","heading":"","text":"注册会计师应当通过采取下列措施，获取充分、适当的审计证据，以确定期初余额是否包含对本期财务报表产生重大影响的错报： （一）确定上期期末余额是否已正确结转至本期，或在适当的情况下已作出重新表述； **（二）确定期初余额是否反映对恰当会计政策的运用；** **（三）实施一项或多项审计程序。** 注册会计师实施的一项或多项审计程序包括： （一）如果上期财务报表已经审计，查阅前任注册会计师的审计工作底稿，以获取有关期初余额的审计证据； （二）评价本期实施的审计程序是否提供了有关期初余额的审计证据； **（三）实施其他专门的审计程序，以获取有关期初余额的审计证据。**","seq":7},{"id":4606,"no":"第九条","heading":"","text":"如果获取的审计证据表明期初余额存在可能对本期财务报表产生重大影响的错报，注册会计师应当实施适合具体情况的追加的审计程序，以确定对本期财务报表的影响。如果认为本期财务报表中存在这类错报，注册会计师应当按照《中国注册会计师审计准则第1251号——评价审计过程中识别出的错报》的规定，就这类错报与适当层级的管理层和治理层进行沟通。","seq":8},{"id":4607,"no":"第十条","heading":"","text":"注册会计师应当获取充分、适当的审计证据，以确定期初余额反映的会计政策是否在本期财务报表中得到一贯运用，以及会计政策的变更是否已按照适用的财务报告编制基础作出恰当的会计处理和适当的列报。","seq":9},{"id":4608,"no":"第十一条","heading":"","text":"如果上期财务报表已由前任注册会计师审计，并发表了非无保留意见，注册会计师应当按照《中国注册会计师审计准则第1211号——重大错报风险的识别和评估》的规定，在评估本期财务报表重大错报风险时，评价导致对上期财务报表发表非无保留意见的事项的影响。 ### 第二节 审计结论和审计报告","seq":10},{"id":4609,"no":"第十二条","heading":"","text":"如果不能获取有关期初余额的充分、适当的审计证据，注册会计师应当按照《中国注册会计师审计准则第1502号——在审计报告中发表非无保留意见》的规定，对财务报表发表保留意见或无法表示意见。","seq":11},{"id":4610,"no":"第十三条","heading":"","text":"如果认为期初余额存在对本期财务报表产生重大影响的错报，且错报的影响未能得到恰当的会计处理或适当的列报，注册会计师应当按照《中国注册会计师审计准则第1502号——在审计报告中发表非无保留意见》的规定，对财务报表发表保留意见或否定意见。","seq":12},{"id":4611,"no":"第十四条","heading":"","text":"如果认为按照适用的财务报告编制基础与期初余额相关的会计政策未能在本期得到一贯运用，或者会计政策的变更未能得到恰当的会计处理或适当的列报，注册会计师应当按照《中国注册会计师审计准则第1502号——在审计报告中发表非无保留意见》的规定，对财务报表发表保留意见或否定意见。","seq":13},{"id":4612,"no":"第十五条","heading":"","text":"如果前任注册会计师对上期财务报表发表了非无保留意见，并且导致发表非无保留意见的事项对本期财务报表仍然相关和重大，注册会计师应当按照《中国注册会计师审计准则第1502号——在审计报告中发表非无保留意见》和《中国注册会计师审计准则第1511号——比较信息：对应数据和比较财务报表》的规定，对本期财务报表发表非无保留意见。 ## 第五章 附则","seq":14},{"id":4613,"no":"第十六条","heading":"","text":"本准则自2023年7月1日起施行。","seq":15}]});
